    val defaultShopTypeKey: String = shopTypes.first().key

    fun findShopType(key: String?): ShopTypePreset? =
        shopTypes.firstOrNull { it.key.equals(key ?: "", ignoreCase = true) }

    fun productsFor(key: String?): List<ProductEntity> =
        findShopType(key)?.products ?: emptyList()

    fun displayNameFor(key: String?): String =
        findShopType(key)?.displayName ?: "My Shop"

    fun categoriesFor(key: String?): List<String> =
        findShopType(key)?.categories ?: emptyList()
